import gzip,glob,csv
for f in sorted(glob.glob('studies/data/raw/*series_matrix.txt.gz')):
    print('=====',f)
    rows={}
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample_'):
            p=next(csv.reader([l.rstrip('\n')],delimiter='\t'))
            rows.setdefault(p[0],[]).append(p[1:])
    ids=rows['!Sample_geo_accession'][0]
    for i,g in enumerate(ids):
        extra=[r[i] for k in rows if k.startswith('!Sample_characteristics') for r in rows[k] ]
        print(g,rows['!Sample_title'][0][i],'|',[e for e in extra if not any(s in e for s in ['age:','gender','ethnicity','tissue orig','cell type','disease'])])

import gzip,glob,csv
for f in sorted(glob.glob('studies/data/raw/*series_matrix.txt.gz'))[2:]:
