            p=next(csv.reader([l.rstrip('\n')],delimiter='\t'))
            rows.setdefault(p[0],[]).append(p[1:])
    ids=rows['!Sample_geo_accession'][0]
    for i,g in enumerate(ids):
        extra=[r[i] for k in rows if k.startswith('!Sample_characteristics') or k.startswith('!Sample_description') or k.startswith('!Sample_source') for r in rows[k] ]
